#!/usr/bin/env bash
# Some portions generated by Codex. Prespecified factorial series; owner must grant CPU window.
set -euo pipefail
cd "$(dirname "$0")/../../.."
: "${CP_A:?}" "${CP_B:?}" "${CP_C:?}" "${CP_D:?}" "${LOCK:?}"
: "${BASELINE_SHA:?Published baseline identity required}" "${COMBINED_SHA:?Published combined identity required}"
: "${SOURCE_PULL_SHA:?Published SOURCE_PULL identity required}" "${WRITER_GUARD_SHA:?Published writer-guard identity required}"
JAVA=${JAVA:-../toolchain/jdk-25.0.5+8/bin/java}
JAVAC=${JAVAC:-../toolchain/jdk-25.0.5+8/bin/javac}
OUT=${OUT:-experiments/threadlocal-audit/source-pull/four-arm-01}
if [[ -e "$OUT" ]]; then echo "Refusing existing output directory: $OUT" >&2; exit 2; fi
mkdir -p "$OUT/harness" "$OUT/tmp"
exec 9>"$LOCK"; flock 9
"$JAVAC" -cp "$CP_D" -d "$OUT/harness" experiments/threadlocal-audit/ThreadLocalQueryBenchmark.java
HARNESS=$(realpath "$OUT/harness"); FIXTURE=$(realpath -m "$OUT/fixture")
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
FLAGS+=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640)
printf '%s\n' "${FLAGS[@]}" > "$OUT/flags.txt"
{
 date -u; "$JAVA" -version
 echo baselineRuntime=previous-measured-c02-semantics; echo A_PUBLISHED="$BASELINE_SHA"; echo D_PUBLISHED="$COMBINED_SHA"
 echo SOURCE_PULL_SHA="$SOURCE_PULL_SHA"; echo WRITER_GUARD_SHA="$WRITER_GUARD_SHA"
 echo combinedRuntime=both-independent-prefix-layers-over-A
 echo localHEADNotRuntimeIdentity; git rev-parse HEAD
 printf 'CP_A=%s\nCP_B=%s\nCP_C=%s\nCP_D=%s\nLOCK=%s\n' "$CP_A" "$CP_B" "$CP_C" "$CP_D" "$LOCK"
 sha256sum experiments/threadlocal-audit/ThreadLocalQueryBenchmark.java
} > "$OUT/environment.txt" 2>&1
# Record all actual class bytes in every classpath directory. Dependencies' JAR hashes are recorded once.
python3 - "$OUT" <<'PY'
import pathlib,os,sys,hashlib,json
out=pathlib.Path(sys.argv[1]); jars={}; arms={}
for a in 'ABCD':
 entries=[]
 for part in os.environ['CP_'+a].split(':'):
  p=pathlib.Path(part); files=sorted(p.rglob('*.class')) if p.is_dir() else [p]
  rows=[]
  for f in files:
   sha=hashlib.sha256(f.read_bytes()).hexdigest()
   if f.suffix=='.jar':jars[str(f)]=sha
   else:rows.append({'path':str(f),'sha256':sha})
  entries.append({'classpathEntry':part,'classes':rows})
 arms[a]=entries
(out/'class-manifest.json').write_text(json.dumps(arms,indent=2))
(out/'dependency-sha256.json').write_text(json.dumps(jars,indent=2))
PY
sha256sum core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/{RepositoryValueIteration,ValueStore}.java > "$OUT/sources.sha256"
run() {
 local arm=$1 regime=$2 log=$3 warm=$4 iterations=$5; local var="CP_$arm"; local cp=${!var}
 local -a cmd=("$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "-Xlog:gc:file=$log.gc.log:time,uptime,level,tags"
  "${FLAGS[@]}" "-Djava.io.tmpdir=$(realpath "$OUT/tmp")" "-Daudit.regime=$regime" -Daudit.shape=narrow
  "-Doverlay.benchmark.warmups=$warm" "-Doverlay.benchmark.fixture=$FIXTURE" -cp "$HARNESS:$cp"
  org.eclipse.rdf4j.sail.lmdb.evaluation.ThreadLocalQueryBenchmark 100 10 "$iterations" true)
 printf '%q ' "${cmd[@]}" > "$log.command"
 "${cmd[@]}" > "$log" 2>&1
}
run A regular "$OUT/reference.log" 0 1
for regime in regular interpreted janino; do
 i=0
 for arm in A B D C B C A D C D B A D A C B; do
  i=$((i+1)); run "$arm" "$regime" "$OUT/$regime-$(printf '%02d' "$i")-$arm.log" 20 10
 done
done
python3 experiments/threadlocal-audit/source-pull/summarize-four-arm.py "$OUT" > "$OUT/summary.json"
